use super::{Element, Node};
use std::fmt::Write;

pub(super) fn diagnostics(root: &Element, grammar: &str) -> String {
    let mut output = String::new();
    if grammar.is_empty() {
        return output;
    }
    let mut pending = vec![(root, "START", Vec::new())];
    while let Some((node, state, path)) = pending.pop() {
        let local = node.tag.rsplit(':').next().unwrap();
        let key = (grammar, state, local, node.namespace.as_str());
        let Ok(index) = RULES.binary_search_by(|r| (r.0, r.1, r.2, r.3).cmp(&key)) else {
            if NAMESPACES.contains(&node.namespace.as_str()) {
                writeln!(
                    output,
                    "Unexpected element '{}' in state : \n\t{}",
                    node.tag,
                    path.join(" -> ")
                )
                .unwrap();
            }
            continue;
        };
        let mut path = path;
        path.push(local);
        for child in node.children.iter().rev() {
            if let Node::Element(child) = child {
                pending.push((child, RULES[index].4, path.clone()));
            }
        }
    }
    output
}

